{"version":3,"file":"request.js","sources":["utils/request.ts"],"sourcesContent":["// src/utils/request.ts\n// @ts-nocheck\n\n// 配置基础地址：支持运行时覆盖\nconst detectBaseURL = (): string => {\n  // 1) 运行时存储覆盖（在微信开发者工具控制台可设置：uni.setStorageSync('BASE_URL', 'http://ip:port')）\n  const stored = typeof uni !== 'undefined' ? uni.getStorageSync('BASE_URL') : '';\n  if (stored) return stored;\n\n  // 2) 全局变量覆盖（在页面注入 window.__API_BASE_URL / globalThis.__API_BASE_URL）\n  const g: any = (typeof globalThis !== 'undefined' ? globalThis : (typeof window !== 'undefined' ? window : {}));\n  if (g && g.__API_BASE_URL) return g.__API_BASE_URL as string;\n\n  // 3) 默认值（本地开发）\n  return 'http://localhost:8095';\n};\n\nconst baseURL = detectBaseURL();\nconst API_PREFIX = (() => {\n  try {\n    return typeof uni !== 'undefined' ? (uni.getStorageSync('API_PREFIX') || '/jeecg-boot') : '/jeecg-boot';\n  } catch (_) {\n    return '/jeecg-boot';\n  }\n})();\n\n// 请求拦截器：添加 token、统一配置等\nconst requestInterceptor = (options) => {\n  // 1. 添加 baseURL（仅当传入相对路径时）\n  if (options.url && !/^https?:\\/\\//i.test(options.url)) {\n    let path = options.url;\n    if (!path.startsWith('/')) path = `/${path}`;\n    // 允许通过 noPrefix 关闭 jeecg-boot 前缀\n    const usePrefix = API_PREFIX && !options?.noPrefix;\n    if (usePrefix) {\n      if (!path.startsWith(API_PREFIX + '/')) {\n        path = API_PREFIX + path;\n      }\n    }\n    options.url = baseURL + path;\n  }\n  // 2. params 合并到 URL（GET/DELETE）\n  const method = (options.method || 'GET').toUpperCase();\n  if (options.params && (method === 'GET' || method === 'DELETE')) {\n    const toUrlEncoded = (obj = {}) => Object.keys(obj)\n      .map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(obj[k] ?? '')}`)\n      .join('&');\n    const query = toUrlEncoded(options.params);\n    if (query) {\n      options.url += (options.url.includes('?') ? '&' : '?') + query;\n    }\n    delete options.params;\n  }\n\n  // 3. Content-Type 与数据体\n  const header = { ...options.header };\n  const contentType = options.contentType || 'json';\n  if (contentType === 'json') {\n    header['Content-Type'] = 'application/json';\n  } else if (contentType === 'form') {\n    header['Content-Type'] = 'application/x-www-form-urlencoded';\n    if (options.data && typeof options.data === 'object') {\n      const toUrlEncoded = (obj = {}) => Object.keys(obj)\n        .map((k) => `${encodeURIComponent(k)}=${encodeURIComponent(obj[k] ?? '')}`)\n        .join('&');\n      options.data = toUrlEncoded(options.data);\n    }\n  } // multipart 由 uni 处理 boundary\n\n  // 4. 添加请求头（如 token）\n  const skipAuth = !!options.skipAuth;\n  const token = uni.getStorageSync('token'); // 从缓存获取 token\n  if (!skipAuth && token) {\n    header['Authorization'] = `Bearer ${token}`;\n    header['X-Access-Token'] = token;\n  }\n  options.header = header;\n  return options;\n};\n\n// 响应拦截器：统一处理错误、格式化数据\nconst responseInterceptor = (response) => {\n  const { data, statusCode } = response;\n  \n  console.log('响应拦截器 - 原始响应:', response);\n  console.log('响应拦截器 - data:', data);\n  \n  // 1. 处理 HTTP 错误（如 404、500）\n  if (statusCode < 200 || statusCode >= 300) {\n    const httpMsg =\n      statusCode === 502\n        ? '网关错误(502)：后端服务不可达或路由未配置'\n        : statusCode === 404\n        ? '接口不存在(404)'\n        : statusCode >= 500\n        ? '服务器错误'\n        : `请求失败: ${statusCode}`;\n    uni.showToast({ title: httpMsg, icon: 'none' });\n    return Promise.reject(new Error(httpMsg));\n  }\n  \n  // 2. 处理后端自定义错误（兼容多种返回结构）\n  // 常见结构 A: { code, message, data, description? }\n  // 常见结构 B: { success, message, data }\n  // 常见结构 C: 直接返回对象/数组/字符串/数字\n  if (data && typeof data === 'object' && ('code' in data || 'success' in data)) {\n    const code = data.code;\n    const success = data.success;\n    const ok = success === true || code === 200 || code === 0;\n    if (!ok) {\n      // 优先显示 description，没有则显示 message\n      const errorMsg = data.description || data.message || '操作失败';\n      uni.showToast({ title: errorMsg, icon: 'none' });\n      return Promise.reject(new Error(errorMsg));\n    }\n    // 统一解包 JEECG 的 result\n    const payload = data.result !== undefined\n      ? data.result\n      : (data.data !== undefined ? data.data : data);\n    return Promise.resolve(payload);\n  }\n\n  // 3. 处理Spring Boot ResponseEntity响应格式\n  // ResponseEntity.ok(data) 的响应结构通常是 { body: actualData, statusCode: 200, ... }\n  if (data && typeof data === 'object' && data.body !== undefined) {\n    console.log('检测到ResponseEntity格式，提取body:', data.body);\n    return Promise.resolve(data.body);\n  }\n\n  // 4. 其他结构：直接返回原始 data\n  console.log('返回原始data:', data);\n  return Promise.resolve(data);\n}\n\n// 封装统一请求方法\nexport const request = (options) => {\n  // 应用请求拦截器\n  const finalOptions = requestInterceptor(options);\n  \n  return new Promise((resolve, reject) => {\n    uni.request({\n      ...finalOptions,\n      timeout: finalOptions.timeout ?? 8000,\n      // 发起请求\n      success: (res) => {\n        // 应用响应拦截器\n        responseInterceptor(res).then(resolve).catch(reject);\n      },\n      // 处理网络错误（如断网/空响应）\n      fail: (err) => {\n        if (!finalOptions.silent) {\n          const msg =\n            typeof err?.errMsg === 'string' && err.errMsg.includes('ERR_EMPTY_RESPONSE')\n              ? '服务器未返回数据（可能端口/HTTPS/防火墙/网关导致）'\n              : '网络连接失败';\n          uni.showToast({ title: msg, icon: 'none' });\n        }\n        reject(err);\n      },\n    });\n  });\n};\n\n// 封装 GET/POST 等快捷方法（简化调用）\nexport const http = {\n  get: (url, params, options) => \n    request({ ...options, url, method: 'GET', params }),\n  \n  post: (url, data, options) => \n    request({ contentType: 'json', ...options, url, method: 'POST', data }),\n  \n  put: (url, data, options) => \n    request({ contentType: 'json', ...options, url, method: 'PUT', data }),\n  \n  delete: (url, params, options) => \n    request({ ...options, url, method: 'DELETE', params }),\n\n  postForm: (url, data, options) =>\n    request({ contentType: 'form', ...options, url, method: 'POST', data }),\n};\n\nexport default http;"],"names":["uni"],"mappings":";;AAIA,MAAM,gBAAgB,MAAc;AAElC,QAAM,SAAS,OAAOA,cAAAA,UAAQ,cAAcA,cAAI,MAAA,eAAe,UAAU,IAAI;AACzE,MAAA;AAAe,WAAA;AAGb,QAAA,IAAU,OAAO,eAAe,cAAc,aAAc,OAAO,WAAW,cAAc,SAAS;AAC3G,MAAI,KAAK,EAAE;AAAgB,WAAO,EAAE;AAG7B,SAAA;AACT;AAEA,MAAM,UAAU,cAAc;AAC9B,MAAM,cAAc,MAAM;AACpB,MAAA;AACF,WAAO,OAAOA,cAAAA,UAAQ,cAAeA,oBAAI,eAAe,YAAY,KAAK,gBAAiB;AAAA,WACnF,GAAG;AACH,WAAA;AAAA,EACT;AACF;AAGA,MAAM,qBAAqB,CAAC,YAAY;AAEtC,MAAI,QAAQ,OAAO,CAAC,gBAAgB,KAAK,QAAQ,GAAG,GAAG;AACrD,QAAI,OAAO,QAAQ;AACf,QAAA,CAAC,KAAK,WAAW,GAAG;AAAG,aAAO,IAAI,IAAI;AAEpC,UAAA,YAAY,cAAc,EAAC,mCAAS;AAC1C,QAAI,WAAW;AACb,UAAI,CAAC,KAAK,WAAW,aAAa,GAAG,GAAG;AACtC,eAAO,aAAa;AAAA,MACtB;AAAA,IACF;AACA,YAAQ,MAAM,UAAU;AAAA,EAC1B;AAEA,QAAM,UAAU,QAAQ,UAAU,OAAO,YAAY;AACrD,MAAI,QAAQ,WAAW,WAAW,SAAS,WAAW,WAAW;AACzD,UAAA,eAAe,CAAC,MAAM,CAAA,MAAO,OAAO,KAAK,GAAG,EAC/C,IAAI,CAAC,MAAM,GAAG,mBAAmB,CAAC,CAAC,IAAI,mBAAmB,IAAI,CAAC,KAAK,EAAE,CAAC,EAAE,EACzE,KAAK,GAAG;AACL,UAAA,QAAQ,aAAa,QAAQ,MAAM;AACzC,QAAI,OAAO;AACT,cAAQ,QAAQ,QAAQ,IAAI,SAAS,GAAG,IAAI,MAAM,OAAO;AAAA,IAC3D;AACA,WAAO,QAAQ;AAAA,EACjB;AAGA,QAAM,SAAS,EAAE,GAAG,QAAQ,OAAO;AAC7B,QAAA,cAAc,QAAQ,eAAe;AAC3C,MAAI,gBAAgB,QAAQ;AAC1B,WAAO,cAAc,IAAI;AAAA,EAAA,WAChB,gBAAgB,QAAQ;AACjC,WAAO,cAAc,IAAI;AACzB,QAAI,QAAQ,QAAQ,OAAO,QAAQ,SAAS,UAAU;AAC9C,YAAA,eAAe,CAAC,MAAM,CAAA,MAAO,OAAO,KAAK,GAAG,EAC/C,IAAI,CAAC,MAAM,GAAG,mBAAmB,CAAC,CAAC,IAAI,mBAAmB,IAAI,CAAC,KAAK,EAAE,CAAC,EAAE,EACzE,KAAK,GAAG;AACH,cAAA,OAAO,aAAa,QAAQ,IAAI;AAAA,IAC1C;AAAA,EACF;AAGM,QAAA,WAAW,CAAC,CAAC,QAAQ;AACrB,QAAA,QAAQA,cAAAA,MAAI,eAAe,OAAO;AACpC,MAAA,CAAC,YAAY,OAAO;AACf,WAAA,eAAe,IAAI,UAAU,KAAK;AACzC,WAAO,gBAAgB,IAAI;AAAA,EAC7B;AACA,UAAQ,SAAS;AACV,SAAA;AACT;AAGA,MAAM,sBAAsB,CAAC,aAAa;AAClC,QAAA,EAAE,MAAM,WAAe,IAAA;AAE7BA,gBAAA,MAAA,MAAA,OAAA,0BAAY,iBAAiB,QAAQ;AACrCA,gBAAA,MAAY,MAAA,OAAA,0BAAA,iBAAiB,IAAI;AAG7B,MAAA,aAAa,OAAO,cAAc,KAAK;AACnC,UAAA,UACJ,eAAe,MACX,4BACA,eAAe,MACf,eACA,cAAc,MACd,UACA,SAAS,U